package local.lito381.server;
import java.util.*;
/** Actual object projection versus exact Source character/item selector split; no inventory/cast/IO. */
public final class SourceObjectTargetRequestPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static void set(Object o,String key,Object value)throws Exception{SourceSignedRecoveryPlan.set(o,key,value);}
 static Protocol.ObjectSpellRequest packet(int skill,long id){return new Protocol.ObjectSpellRequest((skill-1)/8,(skill-1)%8,id);}
 public static void main(String[]args)throws Exception{
  var rows=NativeSkillTargetMetadata.class.getDeclaredField("rows");rows.setAccessible(true);var old=rows.get(null);var previous=NativeAreaMaterialAction.current.get();try{
   var map=new HashMap<Integer,NativeSkillTargetMetadata.Row>();for(int skill:new int[]{26,44,40,148,149})map.put(skill,new NativeSkillTargetMetadata.Row("none",3,10,0,false,1,0,skill));for(int skill:SourceObjectTargetRequestOracle.ITEM_SKILLS)map.put(skill,new NativeSkillTargetMetadata.Row("none",1,10,0,false,1,0,skill));map.put(29,new NativeSkillTargetMetadata.Row("attack",3,10,0,false,1,0,29));rows.set(null,Map.copyOf(map));
   var hub=(GameHub)SourceSignedRecoveryPlan.unsafe().allocateInstance(GameHub.class);var pc=SourceSignedRecoveryPlan.shell(hub,"source");var peer=SourceSignedRecoveryPlan.shell(hub,"peer");var c=SourcePlayerFactoriesPlan.context(pc);set(c,"hub",hub);c.bindings.put(pc,c.caster);var life=NativeSourceControlledDisplay.token(pc);NativeSourceFirstPlayers.remember(c,pc,c.caster,life);NativeSourceFirstPlayers.seal(c);NativeAreaMaterialAction.current.set(c);var oracle=new SourceObjectTargetRequestOracle();
   for(int skill:new int[]{26,44,148,149}){var request=packet(skill,999);var result=NativeSourceObjectTargetRequest.request(request,pc,skill);var source=oracle.evaluate((int)c.caster.object(),999,skill,true);check(result.targetObjectId()==source.target()&&source.item()==0,"actual object none projection follows exact frozen Source character target");check(result.row()==request.row()&&result.column()==request.column()&&result.skillId()==skill&&request.targetObjectId()==999,"original packet/selector preserved");check(NativeSourceObjectTargetRequest.request(result,pc,skill)==result,"nested projection is idempotent");}
   check(SourceObjectTargetRequestOracle.ITEM_SKILLS.size()==5,"five independent fixed Source item-selector cases");for(int skill:SourceObjectTargetRequestOracle.ITEM_SKILLS){var request=packet(skill,123456);var source=oracle.evaluate((int)c.caster.object(),123456,skill,true);check(NativeSourceObjectTargetRequest.itemSelector(skill)&&source.item()==123456&&source.target()==c.caster.object(),"Source keeps raw item selector independently from character self target");check(NativeSourceObjectTargetRequest.request(request,pc,skill)==request,"native inventory request retains exact selected raw item identity");}
   var large=packet(SourceObjectTargetRequestOracle.ITEM_SKILLS.get(0),0xffffffffL);check(NativeSourceObjectTargetRequest.request(large,pc,large.skillId())==large,"all original native raw item ID bits retained without narrowing");var request=packet(148,999);var projected=NativeSourceObjectTargetRequest.request(request,pc,148);NativeAreaMaterialAction.current.remove();check(NativeSourceObjectTargetRequest.request(c,pc,request,148).equals(projected),"actual original post-context pre-Aim object adapter needs no TLS installation");var blind=SourceNoneTargetRequestPlan.packet(40,999,300,301);var blindResult=NativeSourceNoneTargetRequest.request(c,pc,blind,40);check(blindResult.targetObjectId()==c.caster.object()&&blindResult.x()==0&&blindResult.y()==0,"blind original captured pre-Aim attack request uses same frozen source");check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"no installed scope keeps original object payload");NativeAreaMaterialAction.current.set(c);
   set(pc,"selectedCharacter","replacement");check(NativeSourceObjectTargetRequest.request(request,pc,148).equals(projected)&&!NativeSourceSignedRecovery.member(pc,c.caster,c).current(false),"role replacement never becomes a fresh original source proof");set(pc,"selectedCharacter","source");var state=CombatAccess.field(CombatAccess.field(pc,"timedStatus"),"sourcePoisonLifecycle");set(state,"sourceNpcOwner",new Object());check(NativeSourceObjectTargetRequest.request(request,pc,148).equals(projected)&&NativeSourceSignedRecovery.member(pc,c.caster,c).life==life&&!NativeSourceSignedRecovery.member(pc,c.caster,c).current(false),"revival keeps stale original life for existing guards");set(state,"sourceNpcOwner",life);check(NativeSourceObjectTargetRequest.request(request,peer,148)==request&&NativeSourceObjectTargetRequest.request(request,pc,149)==request,"other caster or typed skill mismatch cannot remap payload");var pointed=packet(29,999);check(NativeSourceObjectTargetRequest.request(pointed,pc,29)==pointed,"ordinary specified target/Ctrl request is unchanged");check(NativeSourceObjectTargetRequest.request(null,pc,148)==null,"null parser policy retained");
   var closed=new NativeSourceHealingCast.Cast(null,null,null,Map.of());closed.close();c.nativeSourceHealingCast=closed;check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"closed prior cast does not recapture source");c.nativeSourceHealingCast=null;var first=c.nativeSourceFirstPlayers;c.nativeSourceFirstPlayers=new NativeSourceFirstPlayers.Snapshot(Map.of());check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"missing original source proof never captures a new one");c.nativeSourceFirstPlayers=first;set(c,"phase","WORLD");check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"WORLD exact original object request retained");set(c,"phase","BATTLE");c.nativeSourceFirstPlayers=null;check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"unmarked Context retains original request");c.nativeSourceFirstPlayers=first;rows.set(null,Map.of());check(NativeSourceObjectTargetRequest.request(request,pc,148)==request,"unloaded metadata creates no remap authority");check(NativeSourceObjectTargetRequest.class.getDeclaredFields().length==0,"no retained actor/Context/Frame/row/TLS/registry");
  }finally{rows.set(null,old);if(previous==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(previous);}check(rows.get(null)==old&&NativeAreaMaterialAction.current.get()==previous,"detached rows and scope restored");System.out.println("PASS"+cases+" object-target request exact-Source-character-item-split/raw-ID/preAim/blind/role-life/closed/WORLD contracts; no bound inventory/cast/selection/cost/RNG/HP/role/IO/Main/database/game qualification");
 }
}
